package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.interfaces.IMind;
import org.kanger.interfaces.internal.IData;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
/** QA-only opt-in at actual native validateCommit ingress; no default activation. */
final class ContextSignedCommitMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean bad=false;try{a.run();}catch(Exception expected){bad=true;}require(bad,why);}
 static void create(Path d,String n,String s)throws Exception{ContextNativeCandidateLeaseMatrix.create(d,n,s);}
 static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}
 static void command(Fixture f,String s)throws Exception{ContextNativePendingInspectionMatrix.command(f,s);}
 static final class Guard {
  final Fixture f;int work=WORK,audit=WORK,familyWork=WORK,familyAudit=WORK,models=1000000,calls,rollbackCalls;
  Guard(Fixture f){this.f=f;}
  ContextSignedCandidateInspection.Limits limits(){return new ContextSignedCandidateInspection.Limits(64,8,2,16,WORK,500000,work,audit,64);}
  void install(){f.user.setData((IData)java.lang.reflect.Proxy.newProxyInstance(DB.class.getClassLoader(),DB.class.getInterfaces(),(object,method,args)->{if(method.getName().equals("validateCommit")){synchronized(f.db){f.user.setData(f.db);try{Mind proposed=(Mind)args[0];if(proposed.getNext()==f.mind){++calls;if(f.mind.requirePendingValidationChild(proposed)!=null)++rollbackCalls;f.db.validatePendingSignedProductionCommit(proposed,limits(),familyWork,familyAudit,models);}f.db.validateCommit((IMind)args[0]);}finally{f.user.setData((IData)object);}}return null;}try{return method.invoke(f.db,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}}));}
  void restore(){f.user.setData(f.db);}
 }
 static StorageLifecycleException attempt(Guard g,String text)throws Exception{g.install();try{g.f.mind.query(text,null,false);return null;}catch(StorageLifecycleException e){return e;}finally{g.restore();}}
 static ContextSignedCommitException signed(StorageLifecycleException e,StorageLifecycleErrorCode code){require(e instanceof ContextSignedCommitException&&e.getErrorCode()==code,"distinct typed signed refusal, never old Native/FamilyAudit");return (ContextSignedCommitException)e;}
 static void signedCases()throws Exception{Path d=Files.createTempDirectory("signed-commit-profile-");create(d,"A","!$u seed(u)&&~blocked(u);");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"physical baseline");f.db.connectContext("A");Guard g=new Guard(f);long revision=f.db.getRevision();Set<String> original=primary(f);String bad="!@u seed(u)->blocked(u);",quiet="!@u seed(u)->~blocked(u);";
  ContextSignedCommitException collision=signed(attempt(g,bad),StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(collision.getSignedEvidence()!=null&&!collision.getSignedEvidence().getOppositions().isEmpty()&&collision.getCollisions().isEmpty(),"sealed full signed ledger, no invented plain collisions");collision.getSignedEvidence().check(WORK,1);require(true,"full signed refusal still independently audits after native rollback");for(ContextSignedBranchInspection.Opposition o:collision.getSignedEvidence().getOppositions())require(o.initial&&o.depth==2&&o.sources.size()==2&&o.sources.stream().filter(s->s.localX).count()==1,"actual pending rule plus physical signed witness Source grade2");
  g.audit=1;ContextSignedCommitException noAudit=signed(attempt(g,bad),StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(noAudit.getPhase().equals("signed-refutation-audit")&&noAudit.getSignedEvidence()==null,"unverified real contradiction is INCOMPLETE, no proof prefix");g.audit=WORK;
  Mind child=new Mind(f.mind);try{require(child.compile(quiet,null,false),"actual consistent signed child");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){ContextSignedPendingGuard.Result scoped=lease.qualifySigned(g.limits());require(scoped.status==ContextSignedPendingGuard.Status.SCOPED_QUIESCENT&&scoped.evidence==null,"positive signed profile independently operationally quiescent");}}finally{f.mind.release(child);}
  StorageLifecycleException full=attempt(g,quiet);require(full!=null&&full.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE,"still-open signed complete-family coverage blocks publication");require((full instanceof ContextSignedCommitException&&((ContextSignedCommitException)full).getPhase().equals("full-family-qualification"))||(full instanceof ContextWitnessProductionCommitException&&((ContextWitnessProductionCommitException)full).getFamilyEvaluation().status==ContextProductionFamilyAssembly.Status.INCOMPLETE),"exact existing full-family unsupported verdict preserved");System.out.println("SIGNED_COMMIT_FULL_FAMILY type="+full.getClass().getSimpleName()+" phase="+(full instanceof ContextSignedCommitException?((ContextSignedCommitException)full).getPhase():"witness-verdict"));
  g.familyWork=1;signed(attempt(g,bad),StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(true,"verified signed rejection precedes even bounded full-family phase");g.familyWork=WORK;require(f.db.getRevision()==revision&&primary(f).equals(original),"all signed attempts preserve physical parent knowledge/revision");}
  System.out.println("SIGNED_COMMIT_PROFILE typedExactProof=true noOldAuditCoercion=true quiescenceNotAdmission=true signedCoverageStillOpen=true");
 }
 static void ingress()throws Exception{ingress(false);}
 static void gates()throws Exception{ingress(true);}
 private static void ingress(boolean gates)throws Exception{Path d=Files.createTempDirectory("signed-commit-ingress-");create(d,"A","!left(1); !p(1);");create(d,"B","!right(1); !~p(1);");long durable;String bad="!@u left(u)&&right(u)->p(u);",safe="!@u left(u)&&right(u)->q(u);";
  try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"physical baseline");f.db.connectContext("A");f.db.connectContext("B");f.db.saveConnections(f.mind);Guard g=new Guard(f);long before=f.db.getRevision();Set<String> original=primary(f);ContextSignedCommitException clash=signed(attempt(g,bad),StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(clash.getSignedEvidence()!=null&&clash.getSignedEvidence().getOppositions().stream().anyMatch(o->o.sources.size()==4&&o.xRefuted),"actual four-Source post-barrier rejection");clash.getSignedEvidence().check(WORK,1);require(true,"independent actual cross-cut rejection audit after rollback");
   if(gates){g.familyWork=1;ContextSignedCommitException noFull=signed(attempt(g,safe),StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(noFull.getPhase().equals("full-family-qualification")&&noFull.getSignedEvidence()==null,"scoped quiescence cannot bypass full-family work gate");signed(attempt(g,bad),StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(true,"actual signed-proof refusal first, full-family second");g.familyWork=WORK;
   g.familyAudit=1;StorageLifecycleException old=attempt(g,safe);require(old instanceof ContextProductionCommitException&&old.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE,"existing full-family audit failure remains distinct and mandatory");g.familyAudit=WORK;g.work=1;ContextSignedCommitException bounded=signed(attempt(g,safe),StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(bounded.getSignedEvidence()==null,"native signed work stop has no refutation proof");g.work=WORK;require(f.db.getRevision()==before&&primary(f).equals(original),"all bounded failures before settlement preserve parent");System.out.println("SIGNED_COMMIT_GATES scopedNotApproval=true fullFamilyWorkAndAuditRequired=true proofBeforeFullFamily=true atomic=true");return;}
   require(attempt(g,safe)==null&&f.db.getRevision()>before,"native settlement only after signed, full-family and existing legacy gates");require(primary(f).size()==2&&primary(f).contains(safe)&&primary(f).contains("!anchor(1);"),"only original safe assertion published, never transported facts");durable=f.db.getRevision();
   g.install();try{command(f,"transaction start");Mind retained=(Mind)f.user.getCurrentMind();require(retained.query(bad,null,false),"user prepares real conflicting child");ContextSignedCommitException refused=null;try{command(f,"transaction commit");}catch(ContextSignedCommitException e){refused=e;}require(refused!=null&&refused.getSignedEvidence()!=null&&f.user.getCurrentMind()==retained,"typed refusal keeps exact user child amendable");f.mind.requirePendingPhysicalChild(retained);long revision=f.db.getRevision();command(f,"transaction rollback");require(f.user.getCurrentMind()==f.mind&&f.db.getRevision()==revision&&g.rollbackCalls==1,"both gates validate ACTUAL rollback refresh, retained conflict not imported");}finally{g.restore();}require(primary(f).size()==2&&!primary(f).contains(bad),"rollback discards refused assertion without leakage");}
  try(Fixture f=new Fixture(d,"X")){require(f.db.getRevision()>=durable&&primary(f).size()==2&&primary(f).contains(safe),"durable reopen contains only safe original publication");}
  System.out.println("SIGNED_COMMIT_INGRESS actualTypedRefusal=true mandatoryFullFamilyAndLegacy=true actualSafeWrite=true retainedRollback=true durableReopen=true optInQAOnly=true");
 }
 static void boundary()throws Exception{Path d=Files.createTempDirectory("signed-commit-boundary-");create(d,"A","!$u seed(u)&&~blocked(u);");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"physical baseline");f.db.connectContext("A");Guard g=new Guard(f);long revision=f.db.getRevision();Set<String> original=primary(f);ContextSignedCommitException unsupported=signed(attempt(g,"!@u p(u)||q(u);"),StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(unsupported.getSignedEvidence()==null,"unsupported whole row no sealed evidence");require(f.db.getRevision()==revision&&primary(f).equals(original),"unsupported attempt never publishes");reject(()->ContextSignedCommitException.conflict(null),"cannot fabricate conflict from scalar diagnostics");reject(()->f.db.validatePendingSignedProductionCommit(f.mind,g.limits(),WORK,WORK,1000000),"actual child required");Mind child=new Mind(f.mind);try{require(child.compile("!@u seed(u)->blocked(u);",null,false),"actual conflict child");ContextSignedCommitException refused=null;try{f.db.validatePendingSignedProductionCommit(child,g.limits(),WORK,WORK,1000000);}catch(ContextSignedCommitException e){refused=e;}require(refused!=null&&refused.getSignedEvidence()!=null,"fresh direct pending boundary obtains sealed signed evidence");ContextSignedPendingGuard.Evidence e=refused.getSignedEvidence();reject(()->e.check(1,64),"independent fresh proof budget");e.check(WORK,1);require(true,"exact proof checks at capacity1");reject(()->e.getOppositions().clear(),"immutable opposition summaries");reject(()->f.db.validatePendingSignedProductionCommit(child,g.limits(),0,WORK,1000000),"explicit positive family bounds");}finally{f.mind.release(child);}require(f.db.getRevision()==revision&&primary(f).equals(original),"direct refusal boundary is read-only without settlement");}
  System.out.println("SIGNED_COMMIT_BOUNDARY actualOwningChildRequired=true unsupportedAndBoundsFailClosed=true sealedEvidenceOnly=true noDefaultSwitch=true");
 }
}
